-- Vehicle catalog for TMB: supplier Excel FOB entries and public web inventory snapshots.
create table public.tmb_vehicle_catalog (
  id uuid primary key default gen_random_uuid(),
  source_type text not null check (source_type in ('supplier_excel','tmb_web')),
  source_key text not null unique,
  brand text not null check (length(brand) between 1 and 120),
  model text not null check (length(model) between 1 and 180),
  variant text not null default '',
  year smallint check (year between 1900 and 2100),
  vehicle_type text,
  fuel text,
  transmission text,
  engine text,
  drive_type text,
  color text,
  price numeric(14,2) check (price is null or price >= 0),
  currency text not null default 'USD' check (currency in ('USD','PEN','CNY','EUR')),
  price_label text,
  image_url text,
  source_url text,
  source_reference text,
  raw_data jsonb not null default '{}'::jsonb check (jsonb_typeof(raw_data)='object'),
  is_active boolean not null default true,
  is_published boolean not null default false,
  first_seen_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  last_seen_run_id uuid,
  published_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index tmb_vehicle_catalog_public_idx on public.tmb_vehicle_catalog(is_published,is_active,brand,model);
create index tmb_vehicle_catalog_source_idx on public.tmb_vehicle_catalog(source_type,updated_at desc);
alter table public.tmb_vehicle_catalog enable row level security;
revoke all on public.tmb_vehicle_catalog from public,anon,authenticated;
grant all on public.tmb_vehicle_catalog to service_role;

create table public.tmb_vehicle_catalog_sync_runs (
  id uuid primary key default gen_random_uuid(),
  source text not null check (source in ('tmb_web')),
  status text not null check (status in ('running','completed','failed')),
  started_at timestamptz not null default now(),
  completed_at timestamptz,
  pages_processed integer not null default 0 check (pages_processed >= 0),
  vehicles_seen integer not null default 0 check (vehicles_seen >= 0),
  error_message text,
  triggered_by uuid references public.tmb_sellers(id) on delete set null
);
create index tmb_vehicle_catalog_sync_runs_started_idx on public.tmb_vehicle_catalog_sync_runs(started_at desc);
alter table public.tmb_vehicle_catalog_sync_runs enable row level security;
revoke all on public.tmb_vehicle_catalog_sync_runs from public,anon,authenticated;
grant all on public.tmb_vehicle_catalog_sync_runs to service_role;

create table public.tmb_vehicle_catalog_sync_state (
  id smallint primary key default 1 check (id=1),
  active_run_id uuid references public.tmb_vehicle_catalog_sync_runs(id) on delete set null,
  pending_urls text[] not null default '{}',
  status text not null default 'idle' check (status in ('idle','running','completed','failed')),
  lock_until timestamptz,
  last_attempt_at timestamptz,
  last_success_at timestamptz,
  last_error text,
  pages_processed integer not null default 0,
  vehicles_seen integer not null default 0,
  updated_at timestamptz not null default now()
);
insert into public.tmb_vehicle_catalog_sync_state(id) values (1) on conflict do nothing;
alter table public.tmb_vehicle_catalog_sync_state enable row level security;
revoke all on public.tmb_vehicle_catalog_sync_state from public,anon,authenticated;
grant all on public.tmb_vehicle_catalog_sync_state to service_role;

create or replace function public.tmb_claim_vehicle_catalog_sync(p_lease_seconds integer default 180)
returns boolean language plpgsql security definer set search_path='' as $$
begin
  if p_lease_seconds < 30 or p_lease_seconds > 600 then return false; end if;
  update public.tmb_vehicle_catalog_sync_state
    set lock_until=now()+make_interval(secs=>p_lease_seconds), updated_at=now()
    where id=1 and (lock_until is null or lock_until < now());
  return found;
end $$;
revoke all on function public.tmb_claim_vehicle_catalog_sync(integer) from public,anon,authenticated;
grant execute on function public.tmb_claim_vehicle_catalog_sync(integer) to service_role;

