  currency text, price_label text, source_url text, source_reference text, raw_data jsonb
)
on conflict (source_key) do update set
  brand=excluded.brand,model=excluded.model,variant=excluded.variant,year=excluded.year,
  price=excluded.price,currency=excluded.currency,price_label=excluded.price_label,
  source_reference=excluded.source_reference,raw_data=excluded.raw_data,is_active=true,
  is_published=true,updated_at=now();

create or replace function public.tmb_upsert_scraped_vehicle_catalog(
  p_rows jsonb,
  p_run_id uuid
) returns integer language plpgsql security definer set search_path='' as $$
declare affected integer;
begin
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 200 then
    raise exception 'Lote de catálogo inválido';
  end if;
  if exists (
    select 1 from jsonb_to_recordset(p_rows) as x(source_key text, brand text, model text, source_url text)
    where source_key is null or source_key not like 'hiluxperu:%'
      or brand is null or length(brand) not between 1 and 120
      or model is null or length(model) not between 1 and 180
      or source_url is null or source_url not like 'https://hiluxperu.com/detail/%'
  ) then
    raise exception 'Vehículo extraído inválido';
  end if;
  insert into public.tmb_vehicle_catalog (
    source_type,source_key,brand,model,variant,year,vehicle_type,fuel,transmission,
    engine,drive_type,color,price,currency,price_label,image_url,source_url,
    source_reference,raw_data,is_active,is_published,last_seen_run_id,last_seen_at
  )
  select 'tmb_web',x.source_key,x.brand,x.model,coalesce(x.variant,''),x.year,x.vehicle_type,
    x.fuel,x.transmission,x.engine,x.drive_type,x.color,x.price,coalesce(x.currency,'USD'),
    x.price_label,x.image_url,x.source_url,x.source_reference,coalesce(x.raw_data,'{}'::jsonb),
    true,false,p_run_id,now()
  from jsonb_to_recordset(p_rows) as x(
    source_key text,brand text,model text,variant text,year smallint,vehicle_type text,
    fuel text,transmission text,engine text,drive_type text,color text,price numeric,
    currency text,price_label text,image_url text,source_url text,source_reference text,raw_data jsonb
  )
  on conflict (source_key) do update set
    brand=excluded.brand,model=excluded.model,variant=excluded.variant,year=excluded.year,
    vehicle_type=excluded.vehicle_type,fuel=excluded.fuel,transmission=excluded.transmission,
    engine=excluded.engine,drive_type=excluded.drive_type,color=excluded.color,
    price=excluded.price,currency=excluded.currency,price_label=excluded.price_label,
    image_url=excluded.image_url,source_url=excluded.source_url,
    source_reference=excluded.source_reference,raw_data=excluded.raw_data,is_active=true,
    last_seen_run_id=excluded.last_seen_run_id,last_seen_at=now(),updated_at=now();
  get diagnostics affected = row_count;
  return affected;
end $$;
revoke all on function public.tmb_upsert_scraped_vehicle_catalog(jsonb,uuid) from public,anon,authenticated;
grant execute on function public.tmb_upsert_scraped_vehicle_catalog(jsonb,uuid) to service_role;
